import React, { useEffect, useState } from "react";
import axios from "axios";
import { FaBook, FaCheckCircle } from "react-icons/fa";

function Courses() {
  const [courses, setCourses] = useState([]);

  useEffect(() => {
    axios
      .get("http://127.0.0.1:8000/courses")
      .then((response) => {
        setCourses(response.data.courses);
      })
      .catch((error) => {
        console.error("Error fetching courses:", error);
      });
  }, []);

  const handleEnroll = async (courseId) => {
    const userId = localStorage.getItem("user_id");

    if (!userId) {
      alert("Please login first");
      return;
    }

    try {
      const response = await axios.post("http://127.0.0.1:8000/enroll", {
        user_id: parseInt(userId),
        course_id: courseId,
      });

      alert(response.data.message);
    } catch (error) {
      console.error("Enrollment error:", error);
      alert("Enrollment failed");
    }
  };

  return (
    <div>
      <h2 style={{ color: "#4a148c", marginBottom: "20px" }}>All Courses</h2>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(260px, 1fr))",
          gap: "20px"
        }}
      >
        {courses.map((course) => (
          <div
            key={course.id}
            style={{
              background: "#fff",
              borderRadius: "16px",
              padding: "20px",
              boxShadow: "0 6px 18px rgba(0,0,0,0.08)",
              border: "1px solid #eee"
            }}
          >
            <div style={{ fontSize: "28px", color: "#7b1fa2", marginBottom: "10px" }}>
              <FaBook />
            </div>

            <h3 style={{ marginBottom: "10px", color: "#222" }}>{course.title}</h3>
            <p style={{ color: "#555", minHeight: "50px" }}>{course.description}</p>

            <button
              onClick={() => handleEnroll(course.id)}
              style={{
                marginTop: "12px",
                width: "100%",
                background: "#7b1fa2",
                color: "white",
                border: "none",
                padding: "12px",
                borderRadius: "10px",
                fontWeight: "bold",
                cursor: "pointer",
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                gap: "8px"
              }}
            >
              <FaCheckCircle />
              Enroll Now
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

export default Courses;
